/* isry.itgcms.dyncBrd.mapper.DyncBrdCmnMapper.updateDyncBrdCmnRdcntList 공통팀 유민상*/
UPDATE SBA110 SET

    RDCNT_NOCS = NVL(TO_NUMBER(RDCNT_NOCS), 0) +1

WHERE 1=1
AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO}
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}

mapper.insert:


      SELECT SBA110_SQ01.NEXTVAL AS BBSCTT_ESNTAL_NO
        FROM DUAL



/* isry.itgcms.dyncBrd.mapper.DyncBrdCmnMapper.insertDyncBrdCmnDtlList 공통팀 유민상*/
INSERT INTO SBA110(
      NTABRD_ESNTAL_NO
    , BBSCTT_ESNTAL_NO
    , BBSCTT_SN

        , BBSCTT_TTL_NM


        , BBSCTT_CN


        , ATFINO

    , RLS_YN
    , NTC_MATTER_YN
    , RDCNT_NOCS
    , DEL_YN
    , FRST_RGTR_ID
    , FRST_REG_DT
    , LAST_MDFR_ID
    , LAST_MDFCN_DT
)VALUES(
      #{NTABRD_ESNTAL_NO}
    , #{BBSCTT_ESNTAL_NO}
    , (SELECT NVL(MAX(BBSCTT_SN), 0) +1 FROM SBA110 WHERE NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO} AND DEL_YN = 'N')

        , #{BBSCTT_TTL_NM}


        , #{BBSCTT_CN}


        , #{ATFINO}

    , #{RLS_YN}
    , #{NTC_MATTER_YN}
    , #{RDCNT_NOCS}
    , 'N'
    , #{FRST_RGTR_ID}
    , SYSDATE
    , #{LAST_MDFR_ID}
    , SYSDATE
)

mapper.update:
 /* isry.itgcms.dyncBrd.mapper.DyncBrdCmnMapper.updateDyncBrdCmnDtlList 공통팀 유민상*/
UPDATE SBA110 SET


    BBSCTT_TTL_NM = #{BBSCTT_TTL_NM}


    , BBSCTT_CN = #{BBSCTT_CN}


    , ATFINO = #{ATFINO}

  , RLS_YN = #{RLS_YN}
  , NTC_MATTER_YN = #{NTC_MATTER_YN}
  , LAST_MDFCN_DT = SYSDATE
  , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}

 /* isry.itgcms.dyncBrd.mapper.DyncBrdCmnMapper.deleteDyncBrdCmnDtlList 공통팀 유민상*/
UPDATE SBA110 SET
    DEL_YN = 'Y'
    , LAST_MDFCN_DT = SYSDATE
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}

